import "core-js/modules/web.dom.iterable";
import "core-js/modules/es6.object.keys";
import "core-js/modules/es6.array.sort";
import "core-js/modules/es6.function.name";
import "core-js/modules/es6.number.constructor";
import { upload, deleteFiles, downloadFile, downloadBase64Img, getFiles as _getFiles } from "@/api/oss";
import { getToken, getUid, getDiffTime } from '@/util/auth';
import md5 from 'js-md5';
// import { sm3Hash } from '@/util/jsencrypt'
// import { getSortPostFormDataForUpload } from '@/router/axios'
var uuid = require('uuid');
export default {
  name: "Upload",
  props: {
    //主键id
    businessKey: {
      type: String,
      require: true
    },
    //表名
    tableName: {
      type: String,
      require: true
    },
    //列名
    columName: {
      type: String,
      require: true
    },
    //文件格式限制
    acceptType: {
      type: String,
      require: true
    },
    //文件数量限制
    limitNum: {
      type: Number,
      require: true
    },
    //文件大小限制(单位kb)
    maxFileSize: {
      type: Number,
      require: true
    },
    //只读true只读
    readOnly: {
      type: Boolean,
      require: true
    }
  },
  data: function data() {
    return {
      action: '#',
      // process.env.VUE_APP_BASE_API + '/msdp-system/oss/upload'
      controllerUrl: "/api/system/fileUpload",
      fileList: [],
      data: {
        businessKey: this.businessKey
        // tableName: this.tableName,
        // columName: this.columName
      },
      showLoading: false,
      dialogVisible: false,
      enable: true,
      imgUrl: "",
      //图片路径
      imgName: '',
      headers: {},
      isRepeat: false
    };
  },
  created: function created() {
    //定义界面状态
    if (this.readOnly) {
      //父页面传入false或无参数代表可编辑
      this.enable = false;
    }
    this.getFiles();
  },
  //窗口关闭向父页面传值
  beforeDestroy: function beforeDestroy() {
    var filename = "";
    if (this.fileList.length >= 1) {
      for (var i = 0; i < this.fileList.length; i++) {
        filename += this.fileList[i].name + ";";
      }
    }
    this.$emit("setFileName", filename);
  },
  methods: {
    uploadFile2: function uploadFile2(params) {
      var file = params.file;
      var formData = new FormData();
      formData.append("file", file);
      formData.append("businessKey", data.businessKey);
      upload(formData).then(function (res) {
        params.onSuccess(res);
      }).catch(function (error) {
        params.onError(error);
      });
    },
    secure: function secure() {
      // 对post-form-data请求参数排序
      function getSortPostFormDataForUpload(data) {
        var params = data;
        var sortParams = {};
        // 排序
        var sortKeys = Object.keys(params).sort();
        for (var i = 0; i < sortKeys.length; i++) {
          if (params[sortKeys[i]] !== undefined) {
            sortParams[sortKeys[i]] = params[sortKeys[i]];
          }
        }
        return sortParams;
      }

      // 生成nonce_client
      var nonce_client = md5(uuid.v4());
      // 生成签名  客户端时间戳 + nonce_client + data + uid
      var timestamp = parseInt(new Date().getTime()) + parseInt(getDiffTime());
      var token = 'Bearer' + getToken();
      var sortData = getSortPostFormDataForUpload(this.data);
      // const sign_client = sm3Hash((Object.keys(sortData).length === 0 ? '' : JSON.stringify(sortData)) + timestamp + nonce_client + getUid());
      this.headers['Authorization'] = token;
      this.headers['nonce'] = nonce_client;
      this.headers['ts'] = timestamp;
      // this.headers['sign'] = sign_client;
      this.headers.isImport = true;
    },
    getFiles: function getFiles() {
      var _this = this;
      if (this.businessKey !== undefined) {
        this.showLoading = true;
        _getFiles(this.data).then(function (response) {
          if (response.code === 200) {
            var files = response.data;
            var fileArray = new Array();
            for (var i = 0; i < files.length; i++) {
              var item = {
                name: files[i].fileName,
                url: files[i].ossName,
                columName: files[i].columName,
                tableName: files[i].tableName
              };
              fileArray.push(item);
            }
            _this.fileList = fileArray;
            _this.showLoading = false;
          } else {
            _this.msgError(response.msg);
          }
        });
      }
    },
    //上传成功后
    fileSuccess: function fileSuccess(res, file, fileList) {
      if (res.code === 200) {
        //后台报错
        this.fileList = fileList;
      } else {
        this.msgError("当前文件【" + file.name + "】上传异常，请联系运维人员！");
      }
    },
    //上传之前操作(用于判断是否重名与格式限制)
    beforeUpload: function beforeUpload(file) {
      var extension = file.name.substring(file.name.lastIndexOf('.') + 1);
      if ("" != this.acceptType && null != this.acceptType) {
        if (-1 == this.acceptType.indexOf(extension)) {
          this.msgWarning('支持文件格式【' + this.acceptType + '】！');
          return false;
        }
      }
      for (var i = 0; i < this.fileList.length; i++) {
        if (this.fileList[i].name == file.name) {
          this.msgWarning("当前文件【" + file.name + "】重名，请修改！");
          this.isRepeat = true;
          return false;
        }
      }
      if (null != this.maxFileSize && file.size / 1024 > this.maxFileSize) {
        this.msgWarning("当前文件" + file.name + "超过大小限制，请修改！");
        return false;
      }
      this.secure();
    },
    //删除之前操作
    beforeRemove: function beforeRemove(file, fileList) {
      var _this2 = this;
      if (this.readOnly) {
        this.$message("只读状态不可删除！");
        return false;
      }
      //上传成功的文件删除则给出提示
      if ("success" != file.status) {
        return true;
      }
      return this.$confirm("确认删除【" + file.name + "】？", "提示", {
        confirmButtonText: "确认",
        cancelButtonText: "取消",
        type: "warning"
      }).then(function () {
        _this2.showLoading = true;
      });
    },
    //删除附件
    removeFile: function removeFile(file, fileList) {
      var _this3 = this;
      if (this.isRepeat) {
        this.isRepeat = false;
        return;
      }
      var data = {
        businessKey: this.businessKey,
        tableName: file.tableName,
        columName: file.columName,
        fileName: file.name
      };
      deleteFiles(data).then(function (response) {
        if (response.code === 200) {
          //this.$message.success(response.msg)
          _this3.showLoading = false;
          _this3.fileList = fileList;
        } else {
          _this3.msgError(response.msg);
        }
      });
    },
    //清空附件
    deleteAll: function deleteAll() {
      var _this4 = this;
      if (this.fileList.length <= 0) {
        return;
      }
      this.$confirm("确认清空附件？", "提示", {
        confirmButtonText: "确认",
        cancelButtonText: "取消",
        type: "warning"
      }).then(function () {
        _this4.showLoading = true;
        var data = {
          businessKey: _this4.businessKey
          // tableName: this.tableName,
          // columName: this.columName
        };
        deleteFiles(data).then(function (response) {
          if (response.code === 200) {
            _this4.$message.success(response.msg);
            _this4.showLoading = false;
            _this4.fileList = [];
          } else {
            _this4.msgError(response.msg);
          }
        });
      });
    },
    //附件预览或下载
    downloadFile: function downloadFile(file) {
      var _this5 = this;
      //验证图片正则表达式 jpg,jpeg,png,bmp,gif
      var Regexs = {
        photo: /\jpg$|\jpeg$|\bmp$|\png$|\gif$/i //图片格式
      };
      var reg = Regexs["photo"];
      //请求地址
      var fileName = file.name.substring(file.name.lastIndexOf('.') + 1).toLowerCase();
      if (reg.test(file.name.substring(file.name.lastIndexOf('.') + 1)) || fileName === 'bmp') {
        this.dialogVisible = true;
        var _data = {
          businessKey: this.businessKey,
          tableName: this.tableName,
          columName: this.columName,
          fileName: file.name
        };
        downloadBase64Img(_data).then(function (response) {
          _this5.imgUrl = "data:image/gif;base64," + response.data.img;
          _this5.imgName = file.name;
        });
      } else {
        var _data2 = {
          businessKey: this.businessKey,
          tableName: this.tableName,
          columName: this.columName,
          fileName: file.name
        };
        //非图片格式文件直接下载
        this.download('msdp-system/oss/downloadFile', _data2, file.name);
      }
    },
    //下载附件
    downloadFileByName: function downloadFileByName(flg) {
      if (flg) {//全部下载（暂不使用）
        /*if (this.fileList.length <= 0) {
          return;
        }
        for (let i = 0 ; i < this.fileList.length ; i++) {
          let downLoadUrlNew = downLoadUrl+"&fileName="+this.fileList[i].ossName;
          window.location.href = safeUtil.makeUrl(downLoadUrlNew);
        }*/
      } else {
        var fileName = this.$refs.img.alt;
        var _data3 = {
          businessKey: this.businessKey,
          tableName: this.tableName,
          columName: this.columName,
          fileName: fileName
        };
        this.download('msdp-system/oss/downloadFile', _data3, fileName);
      }
    },
    //数量超过限制给出提示
    handleExceed: function handleExceed() {
      this.msgWarning('当前只可上传' + this.limitNum + '个文件！');
    },
    //上传失败操作
    showError: function showError(err, file) {
      this.msgError('当前文件【' + file.name + '】上传失败！' + err);
    }
  }
};
